import pages as PG
from pages import *
from pages import foreword,glance,reading,story,cards,end,sources,build,covart,link,url,verse
from fig import strip,svg
from sank_data import *
import pages
BASE='/ganesha/festivals/sankashti-chaturthi/'
PARTS_=[('overview','What Saṅkaṣṭī Is','Gaṇeśa’s Monthly Day of Release'),
        ('keeping-the-vow','Keeping the Vow','The Fast, the Pūjā and the Moonrise'),
        ('ganesha-and-the-moon','Gaṇeśa and the Moon','Why the Moon Is Worshipped Tonight'),
        ('angaraki','Aṅgārakī Caturthī','When Saṅkaṣṭī Falls on a Tuesday')]+[(d['slug'],d['name']+' Saṅkaṣṭī',f"{d['mon']}: {d['form']}") for d in SK]
PG.configure(BASE,PARTS_,'red','Saṅkaṣṭī Caturthī','Lord','Saṅkaṣṭī')
PG.OUT='outs/sankashti-chaturthi/'
def L(i,t=None): return pages.link(i,t)
ML=lambda d: L(4+SK.index(d),d['name'])
GA=lambda x,y,s=1: g(x,y,s,ganesha())
NIGHT=lambda w=560,h=160: sky(w,h)
def covg(label,extra=''):
    return covart(label,g(150,196,1.55,ganesha())+g(330,70,1,moonrise(0,0,26))+g(330,196,1.5,lamp())+g(260,196,1.2,modaka())+g(395,196,1.3,durva())+extra)
TWELVE=[('vakratuṇḍam','curved trunk'),('ekadantam','one-tusked'),('kṛṣṇapiṅgākṣam','dark, tawny-eyed'),('gajavaktram','elephant-faced'),('lambodaram','big-bellied'),('vikaṭam','extraordinary'),('vighnarājam','king of obstacles'),('dhūmravarṇam','smoke-coloured'),('bhālacandram','moon on the brow'),('vināyakam','the supreme leader'),('gaṇapatim','lord of the hosts'),('gajānanam','elephant-faced')]

# ---------------- Part 1: overview
i=0
pp=[foreword(i,['Every month, four days after the full moon, as the moon wanes, many homes keep a quiet fast for Gaṇeśa and break it only when the moon rises. This is <b>Saṅkaṣṭī Caturthī</b>, the “fourth day that removes trouble”.',f'This {len(PARTS_)}-part series covers it fully: what the day is, how the vow is kept, why the moon is worshipped, the prized Tuesday Saṅkaṣṭī, and then each of the thirteen monthly Saṅkaṣṭīs in its own article, with the form of Gaṇeśa, the seat, the offering and the story read that night.'],[('z','A fast every month? For Gaṇeśa?'),('b','Twelve a year, thirteen in a leap year. Small, steady, and loved, especially in Maharashtra and Karnataka.')]),
 glance([('What','The fourth lunar day (caturthī) of the dark fortnight, every month'),('For','Gaṇeśa, as remover of troubles (saṅkaṣṭa-hara)'),('Practice','Fast from sunrise; evening pūjā; moonrise; arghya to the moon; then eat'),('Each month','A different name of Gaṇeśa, a different seat (pīṭha), a different story'),('Tuesday','Aṅgārakī: the most prized Saṅkaṣṭī'),('Number','12 a year; 13 with the leap month'),('Its pair','Vināyaka Caturthī in the bright fortnight')],svg(560,160,'Gaṇeśa at night with the moon rising',NIGHT()+GA(180,150,1.2)+g(400,60,1,moonrise(0,0,26))+g(320,150,1.4,lamp()),bg='#20243a')),
 reading('name','THE NAME','Saṅkaṣṭī, Saṅkaṭahara',fig_row('A knot being untied',[(GA(0,0,.9),1),(modaka(),1.6),(durva(),1.6)],['Gaṇeśa','modaka','dūrvā'],gy=160),['<b>Saṅkaṣṭa.</b> Trouble, distress, a tight place. <b>Saṅkaṣṭī</b> (or Saṅkaṣṭa) Caturthī is the fourth day that frees from it.','<b>Other names.</b> Saṅkaṭahara or Saṅkaṣṭahara Caturthī (“trouble-removing”), common in the south; Saṅkaṭ Cauth or Sakaṭ Cauth in the north; Saṅkaṣṭī in Maharashtra and Karnataka.','<b>Caturthī.</b> The fourth tithi of the fortnight, sacred to Gaṇeśa in both fortnights.','<b>The idea.</b> Gaṇeśa is Vighneśvara, lord of obstacles; on this night one asks him to lift the particular trouble one is in.'],[('z','So it’s for people in trouble?'),('b','Everyone, but the name invites you to bring your trouble. That’s the honesty of it.')],'The fourth day <b>that removes trouble</b>.'),
 reading('tithi','THE DARK FOURTH','Where it falls in the month',svg(560,140,'The moon’s phases with the dark-fortnight fourth marked',''.join(f'<circle cx="{40+j*34}" cy="60" r="12" fill="{"#fff8d0" if j<=6 else "#2a2a3a"}"/>' for j in range(15))+'<circle cx="40" cy="60" r="18" fill="none" stroke="#c0392b" stroke-width="3"/>'+lab(40,104,'full moon',11)+'<circle cx="176" cy="60" r="18" fill="none" stroke="#c0392b" stroke-width="3"/>'+lab(176,104,'4th: Saṅkaṣṭī',11)+lab(516,104,'new moon',11)),['<b>The lunar month.</b> Each month has a bright fortnight (śukla), waxing to full moon, and a dark fortnight (kṛṣṇa), waning to new moon. Each has fifteen tithis.','<b>Saṅkaṣṭī.</b> The fourth tithi of the dark fortnight, four days after the full moon.','<b>Moonrise.</b> By then the moon rises late in the evening, some hours after sunset; the fast lasts until it is seen.','<b>Which date.</b> The day kept is the one on which the caturthī is current at moonrise; pañcāṅgas mark it.'],[('z','Why does the moon rise late?'),('b','After full moon it rises about forty to fifty minutes later each night. By the fourth, it’s well after dark.')],'Four days after <b>full moon</b>.'),
 reading('two','TWO CATURTHĪS A MONTH','Vināyaka and Saṅkaṣṭī',svg(560,140,'A bright and a dark moon side by side',g(170,80,1,moonrise(0,0,30,'#fff8d0'))+lab(170,130,'Vināyaka: bright 4th',12)+'<circle cx="390" cy="80" r="30" fill="#2a2a3a"/>'+g(390,80,.8,moonrise(0,0,22))+lab(390,130,'Saṅkaṣṭī: dark 4th',12)),['<b>Vināyaka Caturthī.</b> The bright-fortnight fourth, four days after the new moon; its greatest is Bhādrapada’s Gaṇeśa Caturthī. On it the moon is traditionally <i>not</i> looked at.','<b>Saṅkaṣṭī Caturthī.</b> The dark-fortnight fourth; here the moon is deliberately sought, and the fast ends with it.','<b>Why the contrast.</b> The moon’s story with Gaṇeśa explains both: see '+L(2,'Part 3')+'.','<b>Our other articles.</b> <a href="/ganesha/festivals/ganesha-chaturthi/">Gaṇeśa Caturthī</a> and <a href="/ganesha/festivals/ganesha-jayanti/">Gaṇeśa Jayantī</a>.'],[('z','Don’t look at the moon on one, look for it on the other?'),('b','That’s it. Same moon, same god, two lessons.')],'One avoids the moon, <b>one waits for it</b>.'),
 reading('ganesha','WHO IS GAṆEŚA','The god of beginnings',svg(560,170,'Gaṇeśa seated with his mouse',GA(240,160,1.4)+g(350,160,1.6,mouse())),['<b>Son of Śiva and Pārvatī.</b> The elephant-headed god, worshipped first in every rite.','<b>Vighneśvara.</b> Lord of obstacles: he removes them for the sincere and places them before the proud.','<b>His marks.</b> One tusk, a curved trunk, a large belly, the noose and goad, the modaka, and the mouse that carries him.','<b>More.</b> Our <a href="/ganesha/foundations/who-is-ganesha/">Who is Gaṇeśa</a> and <a href="/ganesha/foundations/form-and-symbols/">form and symbols</a> articles go deeper.'],None,'The <b>lord of obstacles</b>.'),
 cards('thirteen','THE THIRTEEN SAṄKAṢṬĪS','A name for each month',svg(560,70,'Seven small lamps',''.join(g(60+j*73,60,1,lamp()) for j in range(7))),[(('🌸' if n<4 else '☀️' if n<8 else '❄️' if n<12 else '🌙'),d['mon'],ML(d)+f': {d["form"]}.') for n,d in enumerate(SK)],None,'<b>13 names</b>, 13 seats, 13 stories.',intro='Months are given in Karnataka’s (amānta) calendar; the northern name is one month later.'),
 reading('frame','HOW THE STORIES ARE TOLD','The frame of the vrata kathās',fig_row('Pārvatī asks Gaṇeśa',[(devi(),.7),(GA(0,0,.8),1),(person('#5a8ad0'),1),(person('#1d6fb8'),1)],['Pārvatī','Gaṇeśa','Kṛṣṇa','Yudhiṣṭhira'],gy=160),['<b>Pārvatī asks.</b> In the common vrata books each month opens with Pārvatī asking her son which of his forms is worshipped that month, how, and what is eaten.','<b>Gaṇeśa retells.</b> He answers by repeating what Kṛṣṇa told Yudhiṣṭhira when the Pāṇḍavas, in exile, asked how to win back their kingdom.','<b>The story.</b> Then comes the month’s tale, and a closing word of praise (māhātmya).','<b>Source.</b> These kathās circulate in printed vrata books; the common editions do not name a Purāṇa for them, and we mark them as traditional rather than scriptural.'],[('z','So Kṛṣṇa recommended Saṅkaṣṭī too?'),('b','In these books, yes, to Yudhiṣṭhira, just as with Ekādaśī. The exile is the perfect “trouble”.')],'Pārvatī asks, <b>Gaṇeśa tells</b>.'),
 reading('shared','WHAT THE STORIES SHARE','Patterns across the months',svg(560,140,'A knot and a loosened cord',g(180,90,1,'<path d="M-50 0 q25 -30 50 0 q25 30 50 0" fill="none" stroke="#c0392b" stroke-width="6"/><circle r="10" fill="#c0392b"/>')+g(380,90,1,'<path d="M-50 0 q50 -20 100 0" fill="none" stroke="#2a9d6f" stroke-width="6"/>')),['<b>A tight place.</b> A lost kingdom, a missing child, a mocking family, an impossible task.','<b>Scorn first.</b> Often someone mocks the vow, usually in-laws; their change of heart is part of the story.','<b>Faith in small things.</b> A cow-dung Gaṇeśa, laḍḍus from alms, one poor woman’s night of service.','<b>Release.</b> The trouble lifts, and the vow spreads: the family, the king, the whole land take it up.'],None,'Trouble, faith, <b>release</b>.'),
 reading('where','WHERE IT IS KEPT','A pan-Indian vow',svg(560,150,'A temple and a home shrine',g(180,140,1,palace())+g(380,140,1.2,ganesha())),['<b>Maharashtra.</b> Hugely popular; temples of the Aṣṭavināyaka and <a href="/ganesha/temples/siddhivinayak-mumbai/">Siddhivināyaka</a> see crowds, above all on Aṅgārakī.','<b>Karnataka.</b> Saṅkaṣṭī is widely kept at home and in Gaṇapati temples, such as <a href="/ganesha/temples/idagunji/">Idagunji</a> and <a href="/ganesha/temples/bengaluru-dodda-ganapati/">Bengaluru’s Dodda Gaṇapati</a>.','<b>Tamil Nadu.</b> Saṅkaṭahara Caturthī is marked in Piḷḷaiyār temples with evening abhiṣeka.','<b>The north.</b> Several monthly Saṅkaṣṭīs merge with local festivals: Sakaṭ Cauth, Karvā Cauth, Bahulā Caturthī.'],None,'From Mumbai <b>to Madurai</b>.'),
 reading('texts','THE TEXTS BEHIND IT','What is old and what is popular',fig_row('Old books',[(books_stack(),1.4),(book(),1.4)],['',''],gy=None),['<b>Gaṇeśa in the Purāṇas.</b> The Gaṇeśa and Mudgala Purāṇas, both Gāṇapatya works, glorify caturthī worship; the Aṅgārakī story is told in the Gaṇeśa Purāṇa’s Upāsanā Khaṇḍa.','<b>The stotra.</b> The <a href="/ganesha/hymns/sankatanashana-stotra/">Saṅkaṭanāśana Gaṇeśa Stotra</a>, “the hymn that destroys trouble”, is attributed to the Nārada Purāṇa and is the natural prayer of the day.','<b>The vrata kathās.</b> The thirteen monthly stories come from popular vrata books; their Purāṇic source is not given in the common editions.','<b>Our approach.</b> We retell them in our own words and mark where tellings differ.'],None,'Old hymn, <b>popular stories</b>.'),
 end(i,['<b>What.</b> The dark-fortnight caturthī, every month, for Gaṇeśa.','<b>Name.</b> The fourth day that removes trouble.','<b>Practice.</b> Fast to moonrise, pūjā, arghya to the moon, then eat.','<b>Each month.</b> A form, a seat and a story of its own.','<b>Tuesday.</b> Aṅgārakī is the most prized.'],'Part 2: how the vow is kept, from sunrise to moonrise.','What Saṅkaṣṭī is'),
 sources([('Practice:','Drik Panchang, Saṅkaṣṭī Caturthī pages and vrata kathā index; Wikipedia, “Sankashti Chaturthi” (names and pīṭhas by month).'),('Texts:','Saṅkaṭanāśana Gaṇeśa Stotra (Nārada Purāṇa attribution), as on our hymn page.')],'the Purāṇic source of the monthly kathās; regional names of the day.','Retold in our own words; month names in amānta reckoning.')]
build(i,f'PART 1 OF {len(PARTS_)} · GAṆEŚA · EVERY MONTH',covg('Gaṇeśa at night with the moon rising, a lamp, modaka and dūrvā'),'Gaṇeśa’s monthly day of release','First <b>what the day is</b> and where it falls, then the <b>thirteen monthly forms</b>, how their stories are told, and where it is kept.','What Saṅkaṣṭī Caturthī is: the dark-fortnight fourth sacred to Gaṇeśa, the fast to moonrise, the thirteen monthly forms and seats, the frame of the vrata kathās, and where it is kept. Part 1 of the illustrated Saṅkaṣṭī series.',pp)

# ---------------- Part 2: keeping the vow
i=1
pp=[foreword(i,['The Saṅkaṣṭī vow is simple: fast through the day, worship Gaṇeśa in the evening, wait for the moon, offer it water, and then eat. This part goes through it from sunrise to moonrise.','Customs vary by family and region; what follows is the common core, with the variations noted.'],[('z','Is it hard?'),('b','Easier than Ekādaśī for most: it ends at moonrise, not next morning. The waiting is the discipline.')]),
 glance([('Morning','Bath, a lamp, a saṅkalpa (intention)'),('Day','Fast at your level'),('Evening','Gaṇeśa pūjā: dūrvā, red flowers, modaka'),('Story','The month’s vrata kathā'),('Moonrise','Darśana of the moon; arghya'),('Then','Prasāda and the meal'),('Prayer','Saṅkaṭanāśana Stotra')],svg(560,150,'Sun, Gaṇeśa and moon in a row',g(110,80,1.2,sun())+GA(280,140,1.1)+g(450,70,1,moonrise(0,0,24)))),
 reading('morning','SUNRISE: THE INTENTION','Beginning the day',svg(560,150,'A person bathing at dawn with the sun rising',g(160,80,1.3,sun())+g(320,140,1.1,person('#1d6fb8'))+river(560,140)),['<b>Bath.</b> An early bath; the Gajānana kathā adds white sesame to the water.','<b>A lamp.</b> Light a lamp before Gaṇeśa at the home shrine.','<b>Saṅkalpa.</b> A short resolve: to keep the Saṅkaṣṭī vow until moonrise, for a stated purpose if you have one.','<b>The day.</b> Go about your work; many keep their mind on Gaṇeśa’s names through the day.'],[('z','Do I have to say why?'),('b','Many do, because the vow is about a trouble. But a simple “for Gaṇeśa’s grace” is enough.')],'A bath, a lamp, <b>a resolve</b>.'),
 reading('fast','THE FAST','Levels and limits',fig_row('Water, fruit and a single meal',[(kalasha(),1.2),(pot('#c0392b'),1),(pot_rice(),1)],['water only','fruit and milk','one simple meal'],gy=160),['<b>Strict.</b> No food until moonrise, sometimes no water.','<b>Common.</b> Fruit, milk, and fasting foods such as sābudāna, potato, groundnut and rājgirā; no grains.','<b>Light.</b> One simple meal in the day (the Vakratuṇḍa kathā prescribes exactly this).','<b>Care.</b> The sick, the elderly, pregnant women and children are traditionally excused; diabetics and anyone on regular medicine should take medical advice. The moon can rise late; plan for it.'],[('z','So I don’t have to go fully hungry?'),('b','No. Pick a level you can keep month after month. Steady beats heroic.')],'Fast <b>at your level</b>.'),
 reading('puja','THE EVENING PŪJĀ','Worship before moonrise',svg(560,160,'Gaṇeśa with dūrvā, red flowers, modaka and a lamp',GA(200,150,1.2)+g(320,150,1.5,durva())+g(380,150,1.5,modaka())+g(440,150,1.3,lamp())+g(500,150,1,lotus('#e0503a','#c0392b'))),['<b>The image.</b> A picture or image of Gaṇeśa, or a small clay or turmeric Gaṇeśa; some place it on a kalaśa.','<b>Dūrvā.</b> Twenty-one blades of dūrvā grass, often in bunches; it is his favourite offering.','<b>Red.</b> Red flowers (hibiscus especially) and red sandal paste.','<b>Naivedya.</b> Modakas or laḍḍus (sesame laḍḍus in winter); the month’s kathā may name a special dish. Then ārati.'],[('z','Why dūrvā? It’s just grass.'),('b','The story goes that it cooled Gaṇeśa’s burning stomach after he swallowed a fiery demon. Humble and beloved: very Gaṇeśa.')],'Dūrvā, red flowers, <b>modaka</b>.'),
 reading('katha','THE STORY OF THE MONTH','Reading the vrata kathā',svg(560,150,'A grandmother reading a story to children by a lamp',g(200,140,1.1,person('#7a3fa0',seat=True))+g(290,140,.9,child())+g(340,140,.9,child())+g(440,130,1.3,book())),['<b>After the pūjā.</b> The month’s story is read aloud, or listened to, by the family.','<b>Which story.</b> Each month has its own; links to all thirteen are in '+L(0,'Part 1')+'.','<b>Why read it.</b> The stories say hearing them is itself part of the vow’s merit; they also teach the children why the family fasts.','<b>No book?</b> Read our article for the month, or recite the Saṅkaṭanāśana Stotra.'],None,'Every month <b>its own story</b>.'),
 verse('v23','The twelve names (1)','Saṅkaṭanāśana Stotra, verses 2–3',['prathamaṃ vakratuṇḍaṃ ca ekadantaṃ dvitīyakam','tṛtīyaṃ kṛṣṇapiṅgākṣaṃ gajavaktraṃ caturthakam ‖2‖','lambodaraṃ pañcamaṃ ca ṣaṣṭhaṃ vikaṭameva ca','saptamaṃ vighnarājaṃ ca dhūmravarṇaṃ tathāṣṭamam ‖3‖'],svg(200,140,'Gaṇeśa',GA(100,135,1.2)),'First the Curved-trunked, second the One-tusked, third the Dark and Tawny-eyed, fourth the Elephant-mouthed; fifth the Big-bellied, sixth the Extraordinary, seventh the King of Obstacles, eighth the Smoke-coloured.',TWELVE[:8],'Five of these eight are also names of monthly Saṅkaṣṭīs: Vakratuṇḍa, Ekadanta, Lambodara, Vikaṭa and Vighnarāja.',k='<b>Eight names</b> so far.',note='Text as on our <a href="/ganesha/hymns/sankatanashana-stotra/">Saṅkaṭanāśana Stotra</a> page.'),
 verse('v4','The twelve names (2)','Saṅkaṭanāśana Stotra, verse 4',['navamaṃ bhālacandraṃ ca daśamaṃ tu vināyakam','ekādaśaṃ gaṇapatiṃ dvādaśaṃ tu gajānanam ‖4‖'],svg(200,140,'Gaṇeśa with the moon on his brow',GA(100,135,1.2)+'<path d="M86 14 q14 14 28 0 q-14 8 -28 0z" fill="#fff8d0" stroke="#111" stroke-width="2"/>'),'Ninth the Moon-browed, tenth the Leader, eleventh the Lord of Hosts, twelfth the Elephant-faced.',TWELVE[8:]+[('navamam … dvādaśam','ninth … twelfth')],'Bhālacandra and Gajānana are also monthly Saṅkaṣṭī names. So seven of the twelve hymn names are shared with the monthly list; the two lists overlap but are not the same.',k='Twelve names <b>to say tonight</b>.'),
 verse('v56','The promise','Saṅkaṭanāśana Stotra, verses 5–6',['dvādaśaitāni nāmāni trisandhyaṃ yaḥ paṭhennaraḥ','na ca vighnabhayaṃ tasya sarvasiddhiśca jāyate ‖5‖','vidyārthī labhate vidyāṃ dhanārthī labhate dhanam','putrārthī labhate putrānmokṣārthī labhate gatim ‖6‖'],svg(200,140,'A lamp and a book',g(70,120,1.5,lamp())+g(140,110,1.4,book())),'Whoever recites these twelve names at the three junctions of the day has no fear of obstacles, and every success comes. The seeker of learning gains learning, the seeker of wealth gains wealth, the seeker of children gains children, the seeker of liberation gains the goal.',[('dvādaśa etāni nāmāni','these twelve names'),('trisandhyam','at dawn, noon and dusk'),('vighna-bhayam','fear of obstacles'),('vidyārthī','one who seeks learning'),('mokṣārthī','one who seeks liberation'),('gatim','the goal, the final state')],'This is the phala-śruti, the promise of fruit. Note how it meets each seeker where they are, and puts liberation in the same breath as wealth.',k='Each seeker <b>gets what they seek</b>.'),
 reading('moonrise','MOONRISE AND ARGHYA','The end of the fast',svg(560,160,'A woman offering water to the rising moon',NIGHT(560,160)+g(420,60,1,moonrise(0,0,26))+g(220,150,1.2,person('#c0392b'))+'<path d="M240 100 q60 -40 150 -40" fill="none" stroke="#8fb8de" stroke-width="3" stroke-dasharray="6 4"/>',bg='#20243a'),['<b>Waiting.</b> The family waits on the terrace or at a window for the moon. The pañcāṅga gives the expected moonrise for your place.','<b>Darśana.</b> When the moon appears, look at it with folded hands.','<b>Arghya.</b> Pour water (often with flowers, sandal and rice) from a small vessel towards the moon, with a short prayer from your vrata book.','<b>Clouded sky.</b> If clouds hide the moon, many families end the fast at the almanac’s moonrise time, facing its direction. This is custom; follow your family’s practice.'],[('z','The whole street on the terrace?'),('b','In many towns, yes. Children announce it: “Moon’s up!” That shout is part of the festival.')],'Wait, see, <b>offer water</b>.'),
 reading('break','BREAKING THE FAST','Prasāda and the meal',svg(560,140,'A plate with modakas and laḍḍus',g(200,110,1.6,plate())+g(180,104,1.2,modaka())+g(222,104,1.2,laddu())+g(380,110,1.4,lamp())),['<b>First prasāda.</b> Take the modaka or laḍḍu offered to Gaṇeśa.','<b>Sharing.</b> Several kathās say to give part of the offering to a brahmin or a guest; feeding someone before you eat is the spirit of it.','<b>The meal.</b> Then the family meal; many keep it simple.','<b>Next month.</b> The vow is often kept for a set period, a year or more, or for life.'],None,'Prasāda first, <b>then the meal</b>.'),
 reading('temple','AT THE TEMPLE','If you can go',svg(560,150,'A Gaṇeśa temple with devotees',g(280,140,1.1,palace())+g(140,140,1,person('#1d6fb8'))+g(420,140,1,person('#c0392b'))),['<b>Evening abhiṣeka.</b> Many Gaṇapati temples hold a special evening abhiṣeka and pūjā on Saṅkaṣṭī.','<b>Crowds.</b> Expect queues on Aṅgārakī; see '+L(3,'Part 4')+'.','<b>Offerings.</b> Dūrvā garlands, coconuts and modakas are customary.','<b>Back home.</b> Most still break the fast at home after moonrise.'],None,'Temple <b>by evening</b>, home by moonrise.'),
 end(i,['<b>Morning.</b> Bath, lamp, resolve.','<b>Day.</b> Fast at your level.','<b>Evening.</b> Dūrvā, red flowers, modaka; the month’s story.','<b>Moonrise.</b> Darśana and arghya.','<b>Then.</b> Prasāda, sharing, the meal.'],'Part 3: why the moon is worshipped on this night, and avoided on another.','Keeping the vow'),
 sources([('Practice:','Drik Panchang vrata kathās (offerings and fasting rules by month); common household practice.'),('Verses:','Saṅkaṭanāśana Gaṇeśa Stotra, verses 2–6, as published on our hymn page.')],'the arghya prayer (not printed; use your vrata book); the clouded-moon custom varies.','Meanings in our own words.')]
build(i,f'PART 2 OF {len(PARTS_)} · FAST · PŪJĀ · MOONRISE',covg('Gaṇeśa, a lamp and the rising moon'),'The fast, the pūjā and the moonrise','The <b>resolve</b> at sunrise, the <b>fast</b>, the evening <b>pūjā</b>, the story, the <b>twelve names</b>, the <b>moonrise</b> and arghya, and breaking the fast.','How to keep Saṅkaṣṭī Caturthī: the morning resolve, levels of fasting, the evening Gaṇeśa pūjā with dūrvā and modaka, the month’s story, the twelve names of the Saṅkaṭanāśana Stotra, moonrise and arghya, and breaking the fast. Part 2 of the illustrated Saṅkaṣṭī series.',pp)

# ---------------- Part 3: the moon
i=2
pp=[foreword(i,['Why does the Saṅkaṣṭī fast end with the moon? And why, on Gaṇeśa’s great festival in Bhādrapada, are people told <i>not</i> to look at it?','The answer is one story told several ways: the moon laughed at Gaṇeśa, was cursed, and was forgiven. This part tells it and what it means for the night of Saṅkaṣṭī.'],[('z','The moon laughed at Gaṇeśa?'),('b','At his belly, his face, his fall. Pride in one’s beauty: the oldest mistake.')]),
 glance([('The fault','The moon mocks Gaṇeśa'),('The curse','Whoever sees the moon shall be falsely accused'),('Softened','Limited to Bhādrapada’s bright fourth'),('Bhālacandra','Gaṇeśa wears the moon on his brow'),('Syamantaka','Kṛṣṇa, falsely accused after seeing that moon'),('Saṅkaṣṭī','The moon, forgiven, is honoured with arghya')],svg(560,150,'Gaṇeśa and the moon',NIGHT(560,150)+GA(200,140,1.1)+g(400,60,1,moonrise(0,0,26)),bg='#20243a')),
 story('laugh','THE MOON LAUGHS','The story in order',strip('Three panels: Gaṇeśa falls, the moon laughs, Gaṇeśa curses',[panel([(GA(0,0,.6),1),(mouse(),1)],'#20243a',140),panel([(moon(),2.4)],'#20243a',140),panel([(GA(0,0,.6),1)],'#fde4e4',140)],['the fall','the laugh','the curse']),'Tellings differ in detail; this is the common outline.',['One night Gaṇeśa, full of modakas from a feast, was riding home on his mouse. A snake crossed the path, the mouse shied, and Gaṇeśa tumbled; his belly split and the sweets spilled out.','Gaṇeśa tied up his belly with the snake itself.','The moon, proud of his own beauty, watched from the sky and laughed.','Gaṇeśa cursed him: whoever looked at the moon would suffer false accusation. In some tellings the moon was to vanish altogether.','The gods pleaded and the moon repented; Gaṇeśa softened the curse to one night only, the bright fourth of Bhādrapada.'],[('z','So that’s why we don’t look on Gaṇeśa Caturthī.'),('b','Right. And see our <a href="/ganesha/stories/moon-curse/">Moon’s Curse</a> story for the full version.')],'A laugh <b>that cost the moon dearly</b>.'),
 reading('forgiven','THE MOON FORGIVEN','From curse to honour',svg(560,150,'The moon bowing before Gaṇeśa',GA(200,140,1.1)+g(380,90,1.6,moon())),['<b>Repentance.</b> The moon’s apology turns the story.','<b>Penance.</b> In some tellings the moon worships Gaṇeśa on a caturthī and is restored.','<b>The link to Saṅkaṣṭī.</b> Tradition joins the two: on the dark fourth the moon, forgiven, is honoured, and the devotee breaks the fast only after seeing him. We mark this link as traditional interpretation.','<b>Two nights, one lesson.</b> On one night the moon reminds us of pride; on the other, of forgiveness.'],None,'From <b>mockery to arghya</b>.'),
 reading('candra','WHO IS CANDRA','The moon as a god',svg(560,150,'The moon among stars',NIGHT(560,150)+g(280,75,1.6,moonrise(0,0,30)),bg='#20243a'),['<b>Candra, Soma.</b> The moon is a deity in his own right, one of the nine planetary deities, lord of Monday.','<b>His wives.</b> The twenty-seven nakṣatras, daughters of Dakṣa. The moon favoured Rohiṇī alone, and Dakṣa cursed him to waste away.','<b>Waxing and waning.</b> Śiva sheltered him on his head and the curse was softened: he wanes, then grows again. (Purāṇic tellings differ.)','<b>A moon of faults.</b> So the moon is twice a figure of pride cursed and pardoned: by Dakṣa, and by Gaṇeśa.'],[('z','The moon gets cursed a lot.'),('b','Beautiful and vain, in the stories. And each time forgiven. That’s why he’s good company on a night of release.')],'Twice cursed, <b>twice forgiven</b>.'),
 reading('bhalacandra','BHĀLACANDRA','The moon on Gaṇeśa’s brow',svg(560,160,'Gaṇeśa with a crescent moon above his forehead',GA(280,155,1.4)+'<path d="M266 22 q14 14 28 0 q-14 8 -28 0z" fill="#fff8d0" stroke="#111" stroke-width="2"/>'),['<b>The name.</b> Bhālacandra: “moon on the forehead”. Gaṇeśa wears the crescent, as his father Śiva does.','<b>A sign of forgiveness.</b> Wearing the moon shows the quarrel is over; the mocker is now an ornament.','<b>A Saṅkaṣṭī name.</b> Bhālacandra is the name of the Phālguna Saṅkaṣṭī; see '+ML(SK[11])+'.','<b>In the stotra.</b> The ninth of the twelve names in the Saṅkaṭanāśana Stotra.'],[('z','He wears the one who laughed at him?'),('b','That’s grace. Not just forgiving, but honouring.')],'The mocker <b>becomes an ornament</b>.'),
 reading('syamantaka','THE SYAMANTAKA JEWEL','Even Kṛṣṇa was not spared',svg(560,150,'A glowing jewel between two figures',g(170,140,1,vishnu())+'<circle cx="280" cy="80" r="16" fill="#ffd60a" stroke="#111" stroke-width="2"/>'+g(390,140,1,person('#7a5a3a'))),['<b>The tale.</b> Kṛṣṇa, it is said, glimpsed the moon on Bhādrapada’s bright fourth.','<b>The accusation.</b> Soon after, the Syamantaka jewel went missing and Kṛṣṇa was accused of taking it.','<b>The clearing.</b> He tracked it to Jāmbavān’s cave, won it back, and cleared his name. The jewel story is in the Bhāgavata and Viṣṇu Purāṇas; its link to the moon-curse belongs to the Gaṇeśa Caturthī tradition.','<b>The remedy.</b> Hearing the Syamantaka story is the traditional remedy for anyone who sees that moon by mistake.'],None,'False accusation, <b>cleared</b>.'),
 reading('waning','THE WANING MOON','What the timing suggests',svg(560,140,'Moon phases from full to crescent',''.join(g(100+j*90,70,1,moonrise(0,0,22-j*3)) for j in range(5))),['<b>Four days after full.</b> On Saṅkaṣṭī the moon is still bright but diminishing.','<b>An image of trouble.</b> Teachers read it as life after a high point, when things start to go wrong. That is when Saṅkaṣṭī is kept. (Interpretation.)','<b>Waiting.</b> The late moonrise makes the vow a lesson in patience.','<b>Light returns.</b> However late, the moon does rise; that is the promise of the night.'],None,'However late, <b>the moon rises</b>.'),
 reading('arghya','OFFERING WATER TO THE MOON','Candra-arghya',svg(560,160,'Water poured towards the moon',NIGHT(560,160)+g(420,60,1,moonrise(0,0,26))+g(200,150,1.4,kalasha()),bg='#20243a'),['<b>Arghya.</b> Water offered as to an honoured guest, from a small vessel or the cupped hands.','<b>With it.</b> Flowers, sandal paste, a few grains of rice; some add milk.','<b>To whom.</b> To the moon as a deity (Candra), and through him to Gaṇeśa who forgave him.','<b>The prayer.</b> Use the short prayer printed in your family’s vrata book; we do not print one here because we could not verify a single standard text.'],None,'Water for <b>the honoured guest</b>.'),
 reading('children','TELLING CHILDREN','The lesson in a minute',svg(560,150,'A child pointing at the moon',NIGHT(560,150)+g(240,140,1.1,child())+g(420,60,1,moonrise(0,0,24))+'<path d="M250 110 l120 -40" stroke="#fff" stroke-width="2"/>',bg='#20243a'),['<b>The story.</b> The moon laughed when Gaṇeśa fell; Gaṇeśa was hurt and cursed him; the moon said sorry and was forgiven.','<b>Ask them.</b> Have you ever laughed at someone who fell?','<b>The answer.</b> Saying sorry fixed it; and Gaṇeśa even wears the moon now.','<b>Tonight.</b> Let the child spot the moonrise and pour the arghya.'],None,'Don’t laugh at a fall; <b>say sorry if you did</b>.'),
 end(i,['<b>The fault.</b> The moon mocked Gaṇeśa.','<b>The curse.</b> False accusation for those who see him, softened to one night.','<b>Bhālacandra.</b> Gaṇeśa wears the moon as an ornament.','<b>Syamantaka.</b> Even Kṛṣṇa was falsely accused, and cleared.','<b>Saṅkaṣṭī.</b> The forgiven moon is honoured with arghya.'],'Part 4: Aṅgārakī, the Tuesday Saṅkaṣṭī.','Gaṇeśa and the moon'),
 sources([('Story:','Common retellings of the moon-curse (Gaṇeśa Caturthī tradition); Syamantaka in the Bhāgavata (10.56–57) and Viṣṇu Purāṇa (4.13).'),('Our pages:','<a href="/ganesha/stories/moon-curse/">The moon’s curse</a>.')],'the link of the forgiven moon to Saṅkaṣṭī arghya is traditional interpretation; details of the curse differ between tellings.','Retold in our own words.')]
build(i,f'PART 3 OF {len(PARTS_)} · THE MOON · BHĀLACANDRA',covg('Gaṇeśa and the rising moon'),'Why the moon is worshipped tonight','The <b>moon’s laugh</b> and Gaṇeśa’s curse, the <b>forgiveness</b>, Bhālacandra, the <b>Syamantaka</b> jewel, and the meaning of arghya.','Gaṇeśa and the moon: the moon’s mockery and curse, its softening to Bhādrapada’s bright fourth, Bhālacandra, the Syamantaka jewel, and why the moon is honoured with arghya on Saṅkaṣṭī. Part 3 of the illustrated Saṅkaṣṭī series.',pp)

# ---------------- Part 4: Aṅgārakī
i=3
MARS=lambda: '<circle r="22" fill="#c0392b"/><circle cx="-6" cy="-6" r="5" fill="#e0703a" stroke="none"/>'
pp=[foreword(i,['When Saṅkaṣṭī falls on a Tuesday it is called <b>Aṅgārakī</b>, after Aṅgāraka, the planet Mars, lord of Tuesday. It is the most prized Saṅkaṣṭī of all, and Gaṇeśa temples are crowded from dawn.','This part tells who Aṅgāraka is, how he won the day for his name, and how Aṅgārakī is kept.'],[('z','Mars and Gaṇeśa? Odd pair.'),('b','Both red, both connected with Earth and Śiva in the stories. And Mars was a devotee.')]),
 glance([('Name','Aṅgārakī: “of Aṅgāraka”, the glowing coal, Mars'),('When','A Saṅkaṣṭī falling on a Tuesday'),('How often','A few times in some years, none in others'),('Story','Mars’s penance to Gaṇeśa and his boon'),('Source','Gaṇeśa Purāṇa, Upāsanā Khaṇḍa (as commonly cited)'),('Held to be','The most fruitful of Saṅkaṣṭīs'),('Also','A Tuesday Vināyaka Caturthī is sometimes called Aṅgārakī too')],svg(560,150,'Gaṇeśa and the red planet',GA(200,140,1.1)+g(400,70,1.4,MARS()))),
 reading('angaraka','WHO IS AṄGĀRAKA','Mars, son of the Earth',svg(560,150,'The red planet Mars above the earth',g(280,60,1.4,MARS())+'<path d="M80 150 q200 -60 400 0z" fill="#8a6a3a"/>'),['<b>The name.</b> Aṅgāraka means “glowing coal”, for the planet’s red colour. He is also Maṅgala (“auspicious”) and Bhauma (“son of Bhūmi”, the Earth).','<b>Birth.</b> Tellings differ. Many make him the son of the Earth goddess; one has him born from a drop of Śiva’s sweat that fell to earth; the Aṅgārakī story makes the sage Bharadvāja his father and the Earth his foster-mother.','<b>A navagraha.</b> One of the nine planetary deities, lord of Tuesday (Maṅgalavāra).','<b>Red.</b> Like Gaṇeśa’s favourite flowers and sindūra.'],None,'Mars: <b>the glowing coal</b>.'),
 story('story','THE STORY OF AṄGĀRAKĪ','How Mars won the day',strip('Three panels: the Earth raises a red child, the boy does penance, Gaṇeśa grants a boon',[panel([(devi(skin='#8a6a3a'),.55),(child(),1)],'#e9d8c0',140),panel([(S('#c0392b'),.8),(river(140,120),1)],'#cfe8f5',140),panel([(GA(0,0,.6),1),(S('#c0392b'),.7)],'#fde4e4',140)],['raised by the Earth','penance by the Narmadā','the boon']),'As commonly told from the Gaṇeśa Purāṇa; details vary.',['A red child, the son of the sage <b>Bharadvāja</b>, was raised by the Earth goddess until he was seven, then returned to his father.','Bharadvāja taught him the Vedas and initiated him into Gaṇeśa’s mantra; the boy went to the banks of the Narmadā to do penance.','After long penance Gaṇeśa appeared to him, on the dark fourth of Māgha, which was a Tuesday.','Asked for a boon, the boy wished only that his name be joined to Gaṇeśa’s forever.','Gaṇeśa granted it: a caturthī falling on a Tuesday would be called Aṅgārakī, and its keepers would have their wishes fulfilled. The boy became the planet Maṅgala.'],[('z','He just asked for his name next to Gaṇeśa’s?'),('b','The humblest wish in the story, and it gave him the most famous day of the Gaṇeśa calendar.')],'A boy’s wish: <b>my name beside yours</b>.'),
 reading('why','WHY IT IS PRIZED','The merit of a Tuesday Saṅkaṣṭī',svg(560,140,'A calendar page with Tuesday marked',''.join(f'<rect x="{60+j*66}" y="30" width="56" height="70" rx="6" fill="{"#c0392b" if j==2 else "#fff"}" stroke="#111" stroke-width="2"/>'+lab(88+j*66,70,d,12) for j,d in enumerate(['Sun','Mon','Tue','Wed','Thu','Fri','Sat']))),['<b>The boon.</b> Gaṇeśa’s promise to Aṅgāraka is the root of its fame.','<b>Rarity.</b> A Saṅkaṣṭī falls on a Tuesday only a few times in some years and not at all in others, which makes each one an occasion.','<b>A popular claim.</b> Many say one Aṅgārakī equals keeping all the Saṅkaṣṭīs of a year (or of many years). This is devotional praise; we mark it as such.','<b>Maṅgala-doṣa.</b> Some keep it to ease what astrologers call Mars affliction in a horoscope; that is a separate, astrological belief.'],None,'Rare, and <b>richly promised</b>.'),
 reading('mars-ganesha','MARS AND GAṆEŚA','Why they belong together',svg(560,150,'Gaṇeśa beside the red planet',GA(200,140,1.1)+g(380,80,1.4,MARS())),['<b>Colour.</b> Both are red; red flowers and sindūra are offered to both.','<b>Earth.</b> Mars is the Earth’s son; Gaṇeśa’s mouse burrows in the earth, and his body was shaped from earth by Pārvatī in one telling.','<b>Tuesday.</b> Already a day of Gaṇeśa and Hanumān worship in many regions.','<b>Obstacles.</b> Mars is feared as a planet of conflict; Gaṇeśa removes obstacles. The pairing reads naturally. (Interpretation.)'],None,'Two red ones, <b>one Tuesday</b>.'),
 reading('temples','AṄGĀRAKĪ AT THE TEMPLES','The great crowds',svg(560,150,'A long queue at a temple',g(440,140,1.1,palace())+''.join(g(80+j*45,140,.8,person(c)) for j,c in enumerate(['#1d6fb8','#c0392b','#2a9d6f','#7a3fa0','#e0a800','#1d6fb8','#c0392b']))),['<b>Maharashtra.</b> Siddhivināyaka in Mumbai and the eight Aṣṭavināyaka shrines draw vast crowds, many queuing from the night before. See our <a href="/ganesha/temples/ashtavinayaka/">Aṣṭavināyaka</a> guide.','<b>Karnataka.</b> Gaṇapati temples hold special abhiṣeka and pūjā; see <a href="/ganesha/temples/idagunji/">Idagunji</a>.','<b>Tamil Nadu.</b> Piḷḷaiyār temples, such as <a href="/ganesha/temples/pillaiyarpatti/">Piḷḷaiyārpaṭṭi</a>, mark the day.','<b>Plan.</b> If you go, go early, carry water, and be patient; the darśana is often brief.'],None,'Queues <b>from before dawn</b>.'),
 reading('keeping','KEEPING AṄGĀRAKĪ','The same vow, with care',svg(560,150,'Gaṇeśa with dūrvā, red flowers and a lamp',GA(220,140,1.1)+g(340,140,1.5,durva())+g(400,140,1.2,lotus('#e0503a','#c0392b'))+g(460,140,1.3,lamp())),['<b>The vow.</b> Kept exactly like any Saṅkaṣṭī: fast, evening pūjā, the month’s story, moonrise and arghya. See '+L(1,'Part 2')+'.','<b>Extra.</b> Red flowers and dūrvā in abundance; many recite the Gaṇapati Atharvaśīrṣa or the Saṅkaṭanāśana Stotra.','<b>Which story.</b> The month’s own kathā, and the Aṅgāraka story above.','<b>Even a little.</b> Those who cannot fast often offer a few blades of dūrvā at a temple; that too is counted.'],None,'Same vow, <b>more red</b>.'),
 reading('vinayaka','THE BRIGHT-FORTNIGHT AṄGĀRAKĪ','A Tuesday Vināyaka Caturthī',svg(560,140,'A bright moon and a red planet',g(200,70,1,moonrise(0,0,26,'#fff8d0'))+g(380,70,1.4,MARS())),['<b>Also called Aṅgārakī.</b> A Vināyaka Caturthī (bright fourth) that falls on a Tuesday is also called Aṅgārakī in some calendars, especially in Maharashtra.','<b>The difference.</b> On it there is no moonrise vow, and the moon is not specially sought.','<b>Less common usage.</b> When people say “Aṅgārakī” without qualification, they usually mean the Saṅkaṣṭī.','<b>Check.</b> Your pañcāṅga will say which is which.'],None,'Usually means <b>the dark-fortnight one</b>.'),
 reading('children','TELLING CHILDREN','Mars’s wish',svg(560,150,'A boy doing penance by a river',g(240,140,1.1,S('#c0392b'))+river(560,140)+g(420,60,1.2,MARS())),['<b>The story.</b> A red boy, raised by Mother Earth, prayed to Gaṇeśa by a river for years.','<b>Ask them.</b> If Gaṇeśa offered you anything, what would you ask?','<b>The answer.</b> The boy asked only to have his name beside Gaṇeśa’s. And he got the most famous Tuesday of all.','<b>The point.</b> Humble wishes, generously granted.'],None,'<b>Ask humbly</b>, receive richly.'),
 end(i,['<b>What.</b> A Saṅkaṣṭī on a Tuesday.','<b>Name.</b> After Aṅgāraka, Mars, the glowing coal.','<b>Story.</b> Mars’s penance and his wish to be joined to Gaṇeśa’s name.','<b>Prized.</b> Rare and richly promised; huge temple crowds.','<b>Kept.</b> Like any Saṅkaṣṭī, with more red and more dūrvā.'],'Part 5 begins the thirteen monthly Saṅkaṣṭīs, with Caitra’s Vikaṭa.','Aṅgārakī Caturthī')
 ,sources([('Story:','Aṅgāraka and Bharadvāja as commonly cited from the Gaṇeśa Purāṇa, Upāsanā Khaṇḍa (via Wikipedia, “Sankashti Chaturthi”, and devotional summaries); Mudgala and Gaṇeśa Purāṇa references in popular sources.')],'Mars’s birth (several versions); the “equal to a year’s Saṅkaṣṭīs” claim; the precise Purāṇa chapter.','Retold in our own words.')]
build(i,f'PART 4 OF {len(PARTS_)} · TUESDAY · MARS',covg('Gaṇeśa, the moon and the red planet',g(60,60,1,MARS())),'When Saṅkaṣṭī falls on a Tuesday','Who <b>Aṅgāraka</b> is, the <b>story</b> of his boon, why the day is <b>prized</b>, the temple crowds, and how it is kept.','Aṅgārakī Caturthī: the Tuesday Saṅkaṣṭī, named for Aṅgāraka (Mars); the story of his penance and boon from Gaṇeśa, why the day is prized, temple crowds, and how it is kept. Part 4 of the illustrated Saṅkaṣṭī series.',pp)

# ---------------- one article per month
def nxt(n): return SK[n+1] if n+1<len(SK) else None
for n,d in enumerate(SK):
    i=4+n; nm=d['name']; prev=SK[n-1] if n>0 else None; nx=nxt(n)
    adhika=d['mon']=='Adhika Māsa'
    COV=covg(f'Gaṇeśa as {nm} with the moon rising')
    pp=[foreword(i,[f'This article is about <b>{nm} Saṅkaṣṭī</b>, the Saṅkaṣṭī of <b>{d["mon"]}</b>'+('' if adhika else f' (in the northern calendar, {d["pm"]})')+f'. Gaṇeśa is worshipped this month as <b>{d["form"]}</b>, seated on the <b>{d["pitha"]}</b>. The name means {d["mean"]}.',f'Here is the form and its name, the seat, who tells the story, the story itself, its characters, what it teaches and promises, the offering, and how the day is kept. '+('Before it comes '+ML(prev)+'; ' if prev else '')+('after it, '+ML(nx)+'.' if nx else 'It is the last of the thirteen.')],[('z',f'What is {nm} Saṅkaṣṭī known for?'),('b',d['k'].replace('<b>','').replace('</b>','')+'.')]),
     glance([('Name',f'{nm} Saṅkaṣṭī'),('Month (Karnataka)',d['mon']),('Month (north)',d['pm']),('Form',d['form']),('Seat',d['pitha']),('Story',' → '.join(d['caps'])),('Offering',d['offering']),('Promise',d['fruits'])],svg(560,150,f'Gaṇeśa as {nm}',GA(200,140,1.1)+g(400,70,1,moonrise(0,0,24))+g(330,140,1.4,durva()))),
     reading('name',f'THE NAME {nm.upper()}',d['mean'],svg(560,160,f'Gaṇeśa as {nm}',GA(220,150,1.3)+(g(340,150,1.4,lion()) if d['slug']=='heramba' else g(340,150,1.6,mouse()) if d['slug']=='akhuratha' else '<path d="M326 22 q14 14 28 0 q-14 8 -28 0z" fill="#fff8d0" stroke="#111" stroke-width="2"/>' if d['slug']=='bhalacandra' else g(340,150,1.5,modaka()))),[f'<b>{nm}.</b> The name means {d["mean"]}.',f'<b>The full form.</b> The monthly lists call him <b>{d["form"]}</b> this month.',d['lesson'][1] if 'gloss' in d['lesson'][1] else '<b>A name to hold.</b> Say the name through the day; each of the thirteen names is a small meditation on one side of Gaṇeśa.','<b>In the stotra.</b> '+('This name is among the twelve of the Saṅkaṭanāśana Stotra; see '+L(1,'Part 2')+'.' if any(nm.lower()[:5] in t[0] for t in TWELVE) else 'This name is not among the twelve of the Saṅkaṭanāśana Stotra; the monthly list and the hymn overlap only in part.')],None,f'{nm}: <b>{d["mean"].split(",")[0]}</b>.'),
     reading('seat','THE SEAT OF THE MONTH','The pīṭha',svg(560,150,'Gaṇeśa on a lotus seat',g(280,140,1.2,'<path d="M-70 0 q70 -26 140 0z" fill="#f4a6b8"/>')+GA(280,120,1)),[f'<b>The {d["pitha"]}.</b> Each month Gaṇeśa is invoked on a different seat (pīṭha) in the pūjā; this month’s is the {d["pitha"]}.','<b>What a pīṭha is.</b> In formal worship the deity is first given a seat, often visualised as a lotus with petals, before being invoked into the image.','<b>The thirteen seats.</b> They range from Gaṇeśa’s own seats to those of Viṣṇu, Śiva, Durgā, the Sun and Bhuvaneśvarī: Gaṇeśa received in the home of each deity in turn. (Interpretation.)','<b>At home.</b> Families without a priest simply name the seat in the saṅkalpa or invocation; the list is from the common monthly tables.'],None,f'This month: <b>{d["pitha"]}</b>.'),
     reading('teller','WHO TELLS THE STORY','The frame',fig_row('Pārvatī asks Gaṇeśa',[(devi(),.7),(GA(0,0,.8),1),(person('#5a8ad0'),1),(person('#1d6fb8'),1)],['Pārvatī','Gaṇeśa','Kṛṣṇa','Yudhiṣṭhira'],gy=160),[f'<b>The teller.</b> {d["teller"]}','<b>The pattern.</b> The vrata kathās are framed as questions and answers, so each carries the authority of the one who tells it.','<b>The sources.</b> These stories circulate in printed Saṅkaṣṭī vrata books; the common editions do not name a Purāṇa.','<b>Read at the vow.</b> The story is read or heard after the evening pūjā, before moonrise.'],None,'A story <b>within a story</b>.'),
     story('story',f'THE STORY OF {nm.upper()}','The vrata kathā in order',strip(f'Three panels from the story of {nm}',d['strip'],d['caps']),d['lead'],d['steps'],d['talk'],d['k']),
     cards('people','WHO IS WHO','The characters of the story',fig_row('Four figures of the story',[(person('#1d6fb8'),1),(person('#c0392b'),1),(sage('#ff8c1a'),1),(GA(0,0,.8),1)],['','','',''],gy=160),d['chars'],None,'Four figures, <b>one lesson</b>.'),
     reading('lesson','WHAT IT TEACHES','The meaning of the story',svg(560,150,'A loosened knot',g(280,90,1.2,'<path d="M-90 0 q90 -30 180 0" fill="none" stroke="#2a9d6f" stroke-width="6"/>')+GA(280,145,.7)),[d['lesson'][0],d['lesson'][1],'<b>In one line.</b> '+d['k'].replace('<b>','').replace('</b>','')+'.','<b>The family of stories.</b> Like the other twelve, it moves from a tight place to release; see what they share in '+L(0,'Part 1')+'.'],None,'The lesson: <b>'+d['k'].split('<b>')[-1].replace('</b>','')+'</b>.'),
     reading('offering','THE OFFERING','What the vrata book names',svg(560,150,'Offerings on a plate',g(280,120,2,plate())+g(250,112,1.2,modaka())+g(290,112,1.2,laddu())+g(330,116,1.2,durva())),[f'<b>This month.</b> {d["offering"]}','<b>Every month.</b> Dūrvā (twenty-one blades), red flowers, a lamp, modakas or laḍḍus, and arghya to the moon at moonrise.','<b>If you can’t.</b> Simple offerings with devotion are enough; the stories themselves praise a widow’s cow-dung Gaṇeśa and laḍḍus made from alms.','<b>Sharing.</b> Many kathās ask that part of the offering go to a brahmin or guest before the devotee eats.'],None,'The month’s <b>special offering</b>.'),
     reading('fruits','WHAT IT PROMISES','Phala-śruti',svg(560,140,'A full pot with flowers',g(280,120,2,pot('#e0a800'))+g(280,74,1.4,lotus())),[f'<b>The promise.</b> {d["fruits"]}','<b>Kṛṣṇa’s word.</b> Most months close with Kṛṣṇa telling Yudhiṣṭhira that by this vow he will defeat his enemies and regain his kingdom.','<b>Read with sense.</b> The promises encourage; teachers say the real fruit is a mind that turns to Gaṇeśa in trouble rather than despair.','<b>Hearing counts.</b> The kathās say that even hearing the story with faith brings part of the merit.'],None,'The promise, <b>and the real one</b>.'),
     reading('keeping',f'KEEPING {nm.upper()} SAṄKAṢṬĪ','What is special this month',svg(560,150,'A home shrine with Gaṇeśa and a lamp at night',NIGHT(560,150)+GA(220,140,1)+g(330,140,1.3,lamp())+g(440,60,1,moonrise(0,0,22)),bg='#20243a'),[f'<b>Special to this month.</b> {d["custom"]}','<b>The usual vow.</b> Fast from sunrise at your level; evening pūjā with dūrvā and red flowers; read this story; wait for the moon; offer arghya; break the fast. Details are in '+L(1,'Part 2')+'.','<b>On a Tuesday.</b> If it falls on a Tuesday it is also Aṅgārakī; see '+L(3,'Part 4')+'.','<b>Care.</b> The sick, the old, pregnant women and children are traditionally excused from strict fasting.'],None,f'Keep {nm} <b>with its own touch</b>.'),
     reading('calendar','WHEN IT FALLS','Two calendars',svg(560,140,'Two calendar pages with the month names',''.join(f'<rect x="{120+j*200}" y="20" width="120" height="100" rx="8" fill="#fff" stroke="#111" stroke-width="2"/>'+lab(180+j*200,60,t,12)+lab(180+j*200,90,mm,13) for j,(t,mm) in enumerate([('Karnataka',d['mon']),('Northern',d['pm'])]))),([f'<b>Karnataka.</b> In the new-moon-ending (amānta) calendar used in Karnataka, Maharashtra and the south, it is the Saṅkaṣṭī of <b>{d["mon"]}</b>.',f'<b>The north.</b> In the full-moon-ending (pūrṇimānta) calendar, the same day falls in <b>{d["pm"]}</b>, because the dark fortnight there belongs to the next month.','<b>Same day.</b> Only the month name differs; the date is the same.','<b>Your almanac.</b> The pañcāṅga for your place gives the date and the moonrise.'] if not adhika else ['<b>Only in leap years.</b> It comes only when an Adhika Māsa is inserted, roughly every third year.','<b>Which month.</b> The leap month takes the name of the month it precedes (for example Adhika Jyeṣṭha).','<b>Both calendars.</b> The Saṅkaṣṭī of the leap month is the thirteenth in either reckoning.','<b>Your almanac.</b> The pañcāṅga announces the leap month well in advance.']),None,(f'{d["mon"]} in Karnataka, <b>{d["pm"]} in the north</b>.' if not adhika else 'Only <b>in a leap year</b>.')),
     cards('related','RELATED READING','Around this Saṅkaṣṭī',fig_row('Books and lamps',[(book(),1.4),(lamp(),1.4),(book(),1.4)],['','',''],gy=None),[('⬅️','Before',ML(prev) if prev else 'This is the first in our order.'),('➡️','After',ML(nx) if nx else 'The last of the thirteen.'),('📖','The foundations',L(0,'What Saṅkaṣṭī is')+', '+L(1,'Keeping the vow')+', '+L(2,'Gaṇeśa and the moon')+'.'),('🙏','The prayer','<a href="/ganesha/hymns/sankatanashana-stotra/">Saṅkaṭanāśana Stotra</a>, the twelve names.')],None,'Read on <b>through the year</b>.'),
     reading('children','TELLING IT TO CHILDREN','The story in a few lines',svg(560,150,'A grandmother telling a story to two children by a lamp',g(220,140,1.1,person('#7a3fa0',seat=True))+g(320,140,.9,child())+g(370,140,.9,child())+g(470,130,1.2,lamp())),[f'<b>Short version.</b> {d["steps"][0]} {d["steps"][-1]}',f'<b>The question to ask.</b> {d["talk"][0][1]}',f'<b>The answer.</b> {d["talk"][1][1]}','<b>Then.</b> Let the children watch for the moonrise and help with the arghya.'],None,f'{nm}, <b>told in a minute</b>.'),
     end(i,[f'<b>Name.</b> {nm}: {d["mean"].split(",")[0]}.',f'<b>When.</b> {d["mon"]}'+('' if adhika else f' (north: {d["pm"]})')+'.',f'<b>Form and seat.</b> {d["form"]}, {d["pitha"]}.',f'<b>Story.</b> {d["caps"][0]} → {d["caps"][2]}.',f'<b>Lesson.</b> {d["k"].replace("<b>","").replace("</b>","")}.'],('Next: '+PARTS_[i+1][1]+'.') if i+1<len(PARTS_) else 'That completes the thirteen Saṅkaṣṭīs.',f'{nm} Saṅkaṣṭī'),
     sources([('Story:',f'Saṅkaṣṭī vrata kathā for {nm}, as given in popular vrata books; Drik Panchang, “{nm} Sankashti Vrat Katha” (outline and offerings). Names and seats: monthly tables as given in Wikipedia, “Sankashti Chaturthi”.')],('no traditional story could be verified for this month.' if adhika else 'names of minor characters and details differ between editions; the Purāṇic source is not named in the common books.'+(' We could not read the standard text for this month and follow popular retellings.' if d['slug'] in ('vighnaraja','akhuratha') else '')),'Retold in our own words.')]
    build(i,f'PART {i+1} OF {len(PARTS_)} · {d["mon"].upper()} · {nm.upper()}',COV,f'{nm} Saṅkaṣṭī',f'The <b>name</b> and seat, who tells the story, <b>the story</b> in order, its characters, what it <b>teaches</b>, the offering, and <b>how it is kept</b>.',f'{nm} Saṅkaṣṭī ({d["mon"]}): Gaṇeśa as {d["form"]} on the {d["pitha"]}; the vrata kathā, its characters and teaching, the offering, and how the day is kept. Part {i+1} of the illustrated Saṅkaṣṭī Caturthī series.',pp)
